window.ECBA_QUESTION_BANK=window.ECBA_QUESTION_BANK||[];window.ECBA_QUESTION_BANK.push(...[{"id":"q493","domains":[3],"level":1,"tag":"","q":"Who can use the Business Analysis Competency Model to develop competencies?","opts":["Only people directly employed as business analysts","Anyone involved directly or indirectly in the BA profession, regardless of official role or title","Only managers responsible for competency assessments","Only practitioners who have completed the BABOK Guide"],"answer":[1],"why":["The model is not limited to people with formal BA titles.","Correct: the Standard says the model is applicable regardless of official role or title.","The model can support professionals beyond managers.","The Standard does not set completion of a guide as a prerequisite."],"ref":"The Business Analysis Standard v2.0 §4.1, printed p. 13; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":false,"sourceSet":"ecba-set-11.html"},{"id":"q494","domains":[3],"level":1,"tag":"","q":"Which inputs should guide an intentional choice of business analysis approach?","opts":["The outcome to be produced","The context of the change","Relevant organizational policies, procedures, methods, and standards","The assumption that the same approach fits every initiative"],"answer":[0,1,2],"why":["Correct: approach selection begins with the outcome to be produced.","Correct: the approach should fit the context for change.","Correct: organizational environments may require different policies, methods, and standards.","The Standard recognizes that different approaches can be appropriate in different situations."],"ref":"The Business Analysis Standard v2.0 §4.2, printed p. 13; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q495","domains":[3],"level":2,"tag":"","q":"Which statements are characteristic of predictive work?","opts":["It attempts to identify the information needed to create desired value","It plans the work up front and then tracks progress against that plan","It may describe scope, requirements, design, schedule, cost, and testing in planning artifacts","It plans only the next iteration and adjusts based on stakeholder feedback"],"answer":[0,1,2],"why":["Correct: predictive approaches seek to identify information needed to create desired value.","Correct: the work is planned up front and progress is tracked against that plan.","Correct: these are examples of predictive planning documents and baselines.","This describes adaptive iteration and feedback."],"ref":"The Business Analysis Standard v2.0 §4.2.1, printed pp. 14–15; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q496","domains":[3],"level":2,"tag":"","q":"Which features are associated with adaptive work?","opts":["Delivering value in small prioritized increments","Planning the entire initiative in complete detail before beginning","Creating just-enough, just-in-time documentation for an increment","Sharing completed increments with stakeholders to elicit feedback"],"answer":[0,2,3],"why":["Correct: adaptive approaches focus on prioritized increments.","Comprehensive upfront planning is more characteristic of predictive work.","Correct: adaptive work creates just-enough, just-in-time documentation.","Correct: stakeholder feedback on what is created supports learning and adaptation."],"ref":"The Business Analysis Standard v2.0 §4.2.2, printed p. 14; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q497","domains":[3],"level":2,"tag":"","q":"Which conditions can support choosing an adaptive approach?","opts":["The solution addresses complex business needs","The challenge is poorly defined or uncertain","Needs may emerge while the solution is being built","The work is fully defined and can be completed sequentially"],"answer":[0,1,2],"why":["Correct: adaptive approaches can help address complex needs.","Correct: they can be used to explore poorly defined challenges and uncertainty.","Correct: they can manage emerging needs during solution development.","Well-defined, sequential work is listed as a possible fit for predictive approaches."],"ref":"The Business Analysis Standard v2.0 §4.2.1–4.2.2, printed p. 15; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q498","domains":[3],"level":2,"tag":"","q":"Which descriptions fit a hybrid approach?","opts":["An organization uses predictive methods for some initiatives and adaptive methods for others","Different parts of the same initiative use different approaches","Every task combines predictive and adaptive practices in equal measure","The approach may use what works best for the context"],"answer":[0,1,3],"why":["Correct: hybrid can describe different approaches across initiatives.","Correct: a single initiative may also use different approaches in different parts.","Hybrid does not require equal or simultaneous use on every task.","Correct: the Standard describes hybrid as using what works best."],"ref":"The Business Analysis Standard v2.0 §4.2.3, printed p. 14; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q499","domains":[3],"level":3,"tag":"","q":"Which technique is designed to visually define the end-to-end customer experience, including motivations and interactions?","opts":["Process analysis","Data storytelling","Customer journey mapping","Backlog management"],"answer":[2],"why":["Process analysis examines process efficiency and effectiveness.","Data storytelling presents business context or insights through narrative.","Correct: customer journey mapping defines the end-to-end customer experience and interactions.","Backlog management records, tracks, and prioritizes remaining work items."],"ref":"The Business Analysis Standard v2.0 §4.3, printed p. 15; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":false,"sourceSet":"ecba-set-11.html"},{"id":"q500","domains":[3],"level":3,"tag":"","q":"Which technique-description matches are accurate?","opts":["Process analysis examines efficiency and effectiveness to identify value opportunities","Workshops and interviews support collaboration to learn, teach, assess, or review business information","Backlog management provides an engaging narrative to explain data insights","Data storytelling records and prioritizes remaining work items"],"answer":[0,1],"why":["Correct: this describes process analysis.","Correct: this reflects the Standard’s description of workshops and interviews.","This describes backlog management incorrectly; it concerns recording, tracking, and prioritizing work.","This describes data storytelling incorrectly; it uses narrative to communicate context or insights."],"ref":"The Business Analysis Standard v2.0 §4.3, printed p. 15; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q501","domains":[3],"level":3,"tag":"","q":"Which statement best distinguishes the purpose of a requirement from the purpose of a design?","opts":["A requirement represents a need and the value that could be delivered; a design represents a solution and how value might be realized","A requirement is a model of the solution; a design records the original stakeholder need","A requirement describes how value will be realized; a design defines why the change was initiated","A requirement and a design are different names for the same artifact"],"answer":[0],"why":["Correct: requirements represent needs and potential value; designs represent solutions and how value may be realized.","This reverses the roles of requirements and designs.","Business requirements capture why change was initiated; designs describe proposed solutions.","They may be represented similarly, but they serve distinct purposes."],"ref":"The Business Analysis Standard v2.0 §4.4.1, printed p. 16; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":false,"sourceSet":"ecba-set-11.html"},{"id":"q502","domains":[3],"level":3,"tag":"","q":"Which statements describe how requirements and designs interact during an initiative?","opts":["Design work can reveal insights that improve requirements","Changing requirements may lead to design updates","Requirements and designs can be refined through an ongoing feedback cycle","Their purposes are identical because the same techniques may be used"],"answer":[0,1,2],"why":["Correct: designs can uncover insights that enhance requirements.","Correct: changes to requirements can lead to design changes.","Correct: the Standard describes the relationship as interdependent and cyclical.","Shared tasks or techniques do not make their purposes identical."],"ref":"The Business Analysis Standard v2.0 §4.4.1, printed p. 16; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q503","domains":[3],"level":4,"tag":"","q":"Which classifications are among the four main requirement types?","opts":["Business requirements","Stakeholder requirements","Solution requirements","Transition requirements"],"answer":[0,1,2,3],"why":["Correct: business requirements are one of the four types.","Correct: stakeholder requirements are one of the four types.","Correct: solution requirements are one of the four types.","Correct: transition requirements are one of the four types."],"ref":"The Business Analysis Standard v2.0 §4.4.2, printed pp. 16–17; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q504","domains":[3],"level":4,"tag":"","q":"Which statement correctly describes non-functional requirements?","opts":["They define the goals and outcomes that explain why change is initiated","They describe stakeholder needs that bridge business and solution requirements","They specify conditions or qualities that a solution must have","They define temporary capabilities required to move from current to future state"],"answer":[2],"why":["Goals and outcomes for why change is initiated are business requirements.","Stakeholder needs are stakeholder requirements.","Correct: non-functional requirements describe solution conditions or qualities.","Temporary transition capabilities are transition requirements."],"ref":"The Business Analysis Standard v2.0 §4.4.2, printed p. 17; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":false,"sourceSet":"ecba-set-11.html"},{"id":"q505","domains":[3],"level":4,"tag":"","q":"Which statements about transition requirements are accurate?","opts":["They facilitate a transition from current to future state","They are temporary rather than permanent solution requirements","They may address data conversion, training, or business continuity","They define the business goals that initiate a change"],"answer":[0,1,2],"why":["Correct: transition requirements help facilitate movement between states.","Correct: the Standard identifies them as temporary.","Correct: these are examples of areas they may address.","Business requirements state the goals and outcomes for why change is initiated."],"ref":"The Business Analysis Standard v2.0 §4.4.2, printed p. 17; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q506","domains":[3],"level":4,"tag":"","q":"Which outcomes can requirements and design traceability support?","opts":["Identifying the origin and lineage of an item","Assessing which related items may be affected by a change","Detecting missing requirements or solution components with no supporting requirement or design","Determining whether a proposed solution is the least expensive option"],"answer":[0,1,2],"why":["Correct: traceability records lineage back to the original need.","Correct: linked relationships help identify items that may be affected by change.","Correct: trace models can reveal gaps or unsupported components.","Cost comparison is an analysis activity, not a traceability capability."],"ref":"The Business Analysis Standard v2.0 §4.4.3, printed p. 18; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q507","domains":[3],"level":5,"tag":"","q":"Which actions reflect business analysis contributions to security integration?","opts":["Help identify security risks and consider safety measures","Facilitate collaboration between technical and non-technical stakeholders","Align security initiatives with organizational objectives","Assume the BA must be the security subject matter expert"],"answer":[0,1,2],"why":["Correct: identifying security risks and considering safety measures are described contributions.","Correct: BAs can help diverse stakeholders collaborate on security.","Correct: security initiatives should align with organizational objectives.","The Standard says BAs do not necessarily need to be subject matter experts."],"ref":"The Business Analysis Standard v2.0 §4.5.1, printed p. 18; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q508","domains":[3],"level":5,"tag":"","q":"Which practices align with ethical analysis?","opts":["Consider and eliminate personal bias in analysis","Ensure stakeholder needs are met ethically while considering value","Use the IIBA Code of Ethical Conduct and Professional Standards for ethical guidance","Treat the highest-value option as automatically ethical"],"answer":[0,1,2],"why":["Correct: the Standard calls for careful analysis that eliminates personal biases.","Correct: ethical analysis considers stakeholder needs and value.","Correct: the IIBA code provides ethical guidance for judgement calls.","The best-value option and ethical option may not align."],"ref":"The Business Analysis Standard v2.0 §4.5.2, printed p. 18; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q509","domains":[3],"level":5,"tag":"","q":"Which statements reflect inclusion and sustainability in Section 4.5?","opts":["Inclusion actively seeks and amplifies diverse perspectives","Diverse voices can strengthen innovation and creative problem-solving","Sustainability includes meeting current needs while considering future resources and social and economic outcomes","Inclusion is complete once each stakeholder group has a representative listed"],"answer":[0,1,2],"why":["Correct: inclusion goes beyond representation to actively cultivate and amplify diverse perspectives.","Correct: the Standard links diverse perspectives with innovation and creative problem-solving.","Correct: sustainability includes environmental, social, health, and economic dimensions.","Inclusion also involves enabling meaningful contribution and belonging, not only listing representation."],"ref":"The Business Analysis Standard v2.0 §4.5.3–4.5.4, printed p. 19; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q510","domains":[3],"level":5,"tag":"","q":"Which models can organizations use to deliver business analysis services?","opts":["A Centre of Excellence","A Community of Practice","Business Analysis as a Service","Distributing business analysis across business units"],"answer":[0,1,2,3],"why":["Correct: a Centre of Excellence is one delivery form.","Correct: a Community of Practice is one delivery form.","Correct: BA as a Service may use specialized providers.","Correct: BA functions may also be embedded across business units."],"ref":"The Business Analysis Standard v2.0 §4.6, printed p. 20; ECBA Exam Blueprint v1.12 p. 2, Domain 3","multi":true,"sourceSet":"ecba-set-11.html"},{"id":"q511","domains":[4],"level":1,"tag":"","q":"What is the main purpose of planning the business analysis approach?","opts":["Determine how business analysis work will be performed and governed for the change","Define the solution components that will satisfy the business need","Approve the requirements before elicitation begins","Measure whether the implemented solution achieved its benefits"],"answer":[0],"why":["Correct: this task determines how the BA work will be conducted, tailored to the initiative.","Solution definition is addressed through later analysis and design work.","Requirements approval is handled through governance; it is not the purpose of planning the approach.","Post-implementation benefit assessment is not this task’s purpose."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–30; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q512","domains":[4],"level":1,"tag":"","q":"What is the primary focus of planning business analysis governance?","opts":["Establishing how decisions about requirements and designs will be made","Selecting the modeling notation for every deliverable","Defining the future-state operating model","Measuring the quality of the implemented solution"],"answer":[0],"why":["Correct: governance defines decision-making processes, responsibilities, and authority for requirements and designs.","Notation selection may be part of planning analysis work but is not the core governance focus.","Future-state definition is addressed in strategy and solution analysis.","Solution quality is assessed through solution evaluation and related work."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–41; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q513","domains":[4],"level":1,"tag":"","q":"What is the intended result of identifying business analysis performance improvements?","opts":["A set of opportunities and recommended actions for improving BA performance","A revised business need for the initiative","A prioritized list of solution features","A final determination that the solution is valuable"],"answer":[0],"why":["Correct: the task identifies improvement opportunities and recommends actions to improve BA performance.","The business need is understood through other analysis tasks.","Feature prioritization is not the purpose of this task.","Solution value assessment is distinct from BA process improvement."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–50; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q514","domains":[4],"level":1,"tag":"","q":"Which item is an input to Plan Business Analysis Approach?","opts":["Business need","Approved solution design","Solution performance measures","Requirements change request"],"answer":[0],"why":["Correct: the business need informs the approach to the analysis work.","A solution design is not a required input to planning the approach.","Solution performance measures are associated with evaluating performance, not this task input.","Change requests are assessed through requirements change assessment."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–30; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q515","domains":[4],"level":1,"tag":"","q":"Which input is used in Plan Business Analysis Governance?","opts":["Business analysis approach","Business need","Solution performance measures","Current-state description"],"answer":[0],"why":["Correct: the planned BA approach informs the governance approach, including decision processes and responsibilities.","The business need is an input to planning the BA approach, not the specified input to Plan Business Analysis Governance.","Solution performance measures support performance analysis, not governance planning.","Current-state information supports current-state analysis and change strategy, not this task input."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–41; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q516","domains":[4],"level":1,"tag":"","q":"Which input most directly supports the task of identifying BA performance improvements?","opts":["Business analysis performance assessment","Solution scope","Requirements architecture","Future-state description"],"answer":[0],"why":["Correct: the assessment provides evidence about BA performance and improvement needs.","Solution scope is not the direct input to this task.","Requirements architecture supports requirements organization, not BA performance assessment.","A future-state description does not directly assess BA performance."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–50; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q517","domains":[4],"level":2,"tag":"","q":"Which considerations are relevant when tailoring a business analysis approach?","opts":["The business need and initiative context","The organization’s culture and existing processes","The availability and engagement of stakeholders","The selected solution technology as the only determining factor"],"answer":[0,1,2],"why":["Correct: the business need and context influence the approach.","Correct: organizational culture and processes are relevant context.","Correct: stakeholder availability and engagement may affect how BA work is planned.","Technology may be one consideration, but it does not alone determine the approach."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–30; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q518","domains":[4],"level":2,"tag":"","q":"Which guideline or tool can help a BA select an appropriate approach?","opts":["Methodologies and frameworks","Requirements approval record","Solution performance report","Requirements traceability matrix as the sole basis"],"answer":[0],"why":["Correct: methodologies and frameworks guide the selection and tailoring of the BA approach.","Approval records support governance decisions, not approach selection by themselves.","Performance reports usually inform evaluation rather than initial approach selection.","Traceability can support change analysis but is not the sole basis for selecting an approach."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–30; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q519","domains":[4],"level":2,"tag":"","q":"Which techniques may support planning the BA approach?","opts":["Estimation","Risk analysis and management","Lessons learned","Solution testing"],"answer":[0,1,2],"why":["Correct: estimation can help plan effort and timing.","Correct: risk analysis supports planning an approach responsive to uncertainty.","Correct: lessons learned can inform the approach for the current work.","Solution testing evaluates a solution; it is not a core approach-planning technique."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–30; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q520","domains":[4],"level":2,"tag":"","q":"Which matters are established through business analysis governance?","opts":["Decision authority and responsibility","Approval and review processes","How proposed changes are managed","The detailed content of every solution requirement"],"answer":[0,1,2],"why":["Correct: governance identifies who is accountable for decisions.","Correct: governance can define how approvals and reviews occur.","Correct: governance establishes the process for decisions about changes.","Requirement content is developed and maintained through requirements analysis and management."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–41; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q521","domains":[4],"level":2,"tag":"","q":"Which stakeholder roles are commonly involved in defining or agreeing on BA governance?","opts":["Sponsor","Project manager","Domain subject matter expert","Only the implementation team"],"answer":[0,1,2],"why":["Correct: the sponsor may establish or approve decision authority and governance expectations.","Correct: the project manager coordinates project decision processes and governance alignment.","Correct: domain SMEs contribute to decision processes affecting business requirements and designs.","Implementation team members may contribute, but governance is not limited to them."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–41; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q522","domains":[4],"level":2,"tag":"","q":"Which techniques are suited to identifying BA performance improvement opportunities?","opts":["Lessons learned","Root cause analysis","Metrics and key performance indicators","Requirements verification as the only technique"],"answer":[0,1,2],"why":["Correct: lessons learned can reveal recurring strengths and improvement needs.","Correct: root cause analysis can identify underlying causes of performance issues.","Correct: metrics and KPIs provide evidence for evaluating performance.","Verification checks requirements quality; it does not alone identify broader BA performance improvements."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–50; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q523","domains":[4],"level":3,"tag":"","q":"Which statements correctly relate performance measures to improvement work?","opts":["Measures should be interpreted against relevant objectives or expectations","A performance gap can indicate an opportunity for improvement","A measure alone establishes the cause of a performance problem","Improvement actions should be informed by analysis of performance evidence"],"answer":[0,1,3],"why":["Correct: measures need an appropriate reference such as a target or objective.","Correct: a gap can indicate where improvement may be needed.","A measure can indicate a gap but does not by itself establish its cause.","Correct: improvement recommendations should follow analysis of relevant evidence."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–50; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q524","domains":[4],"level":3,"tag":"","q":"Which techniques can help establish or operate governance decisions?","opts":["Decision analysis","Prioritization","Reviews","Process modelling as the required approval authority"],"answer":[0,1,2],"why":["Correct: decision analysis can support structured governance decisions.","Correct: prioritization is commonly governed because it resolves relative importance.","Correct: reviews can support formal decision and approval points.","Process models may describe work, but they do not themselves provide approval authority."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–41; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q525","domains":[4],"level":3,"tag":"","q":"Which stakeholders are relevant when planning the business analysis approach?","opts":["Project manager","Sponsor","Domain subject matter expert","Only the business analyst performing the work"],"answer":[0,1,2],"why":["Correct: the project manager can align the BA approach with project planning and constraints.","Correct: the sponsor can provide direction on the business need and expectations.","Correct: domain SMEs inform the context and knowledge needed for analysis.","The BA contributes, but planning should consider relevant stakeholders rather than only the BA."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–30; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q526","domains":[4],"level":3,"tag":"","q":"Which statements describe appropriate performance-improvement analysis?","opts":["Compare observed performance with relevant expectations or measures","Investigate causes before recommending corrective actions","Assume any deviation is caused by individual BA performance","Use organizational performance information where it is relevant"],"answer":[0,1,3],"why":["Correct: comparison with expectations can identify performance gaps.","Correct: understanding causes helps ensure recommendations address the issue.","A deviation may have process, organizational, or contextual causes; it should not be presumed individual.","Correct: organizational measures can provide useful context for improvement analysis."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–50; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q527","domains":[4],"level":3,"tag":"","q":"What does requirements traceability maintain?","opts":["Relationships between requirements and related elements such as their source or design","A decision record proving that a requirement was approved","The detailed rationale for why a requirement is valuable","The actual test results for every requirement"],"answer":[0],"why":["Correct: traceability captures relationships that support understanding and analysis.","Approval status may be tracked, but it is not the definition of traceability.","Rationale may be documented as an attribute; traceability specifically records relationships.","Test results are verification evidence, not the trace relationship itself."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 78–82; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q528","domains":[4],"level":3,"tag":"","q":"What is the purpose of assessing a proposed requirements change?","opts":["Understand its implications so an authorized decision can be made","Update the requirement immediately to preserve a single current version","Determine whether the requester has sufficient authority to change the baseline","Verify only whether the wording is clear"],"answer":[0],"why":["Correct: assessment evaluates the change and its impacts to support a decision.","The requirement is updated according to the decision and change process.","Decision rights are established by governance; assessment evaluates the proposal.","Clarity may matter, but assessment also considers impacts and value."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 94–97; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q529","domains":[4],"level":4,"tag":"","q":"Which statements describe the purpose of analyzing the current state?","opts":["Understand the existing environment relevant to the business need","Identify problems, causes, capabilities, and constraints that matter to the change","Define the transition plan to the future state","Establish a basis for determining whether change is necessary"],"answer":[0,1,3],"why":["Correct: current-state analysis examines conditions relevant to the need.","Correct: current capabilities, issues, causes, and constraints help characterize the state.","Transition planning is part of defining a change strategy.","Correct: current-state understanding helps evaluate the need for change."],"ref":"BABOK Guide v3 §6.1 Analyze Current State, printed pp. 103–109; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q530","domains":[4],"level":4,"tag":"","q":"Which elements may be addressed by a change strategy?","opts":["How the enterprise transitions from current to future state","The sequencing or timing of change initiatives","Transition risks, readiness, and constraints","Only the detailed future-state model"],"answer":[0,1,2],"why":["Correct: a change strategy describes how transition can occur.","Correct: sequencing and timing can be central to the transition approach.","Correct: readiness and constraints affect feasible change.","A future-state model alone does not explain how the organization reaches it."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–130; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q531","domains":[4],"level":4,"tag":"","q":"Which activities support sound analysis of performance measures?","opts":["Compare actual results with relevant targets or baselines","Interpret measures in relation to the intended outcome","Consider trends and context","Treat a favorable measure as conclusive proof that all needs are met"],"answer":[0,1,2],"why":["Correct: targets and baselines provide comparison points.","Correct: measures are interpreted against the outcome they are meant to indicate.","Correct: trends and context can explain performance patterns.","A favorable measure may be incomplete or misaligned and does not prove every need is met."],"ref":"BABOK Guide v3 §8.2 Analyze Performance Measures, printed pp. 170–172; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q532","domains":[4],"level":4,"tag":"","q":"What is the focus of assessing enterprise limitations?","opts":["Identify conditions that constrain solution options, implementation, or value","Determine whether the solution meets each functional requirement","Confirm that every limitation is permanent and cannot be changed","Replace the business need with a list of organizational constraints"],"answer":[0],"why":["Correct: limitations are conditions that can constrain options, implementation, or realized value.","Functional requirement satisfaction is addressed through solution evaluation.","Some limitations may be changed or mitigated; assessment should establish their nature.","Limitations inform analysis of the need; they do not replace the business need."],"ref":"BABOK Guide v3 §8.4 Assess Enterprise Limitations, printed pp. 178–182; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q533","domains":[4],"level":4,"tag":"","q":"Which statements describe uses of traceability?","opts":["Support impact analysis when a requirement changes","Help identify coverage or relationships to solution components","Establish decision authority for approving changes","Connect a requirement to its source or rationale"],"answer":[0,1,3],"why":["Correct: relationships help identify potential impacts of a change.","Correct: trace links can help assess coverage and related designs or components.","Decision authority is established through governance, not traceability.","Correct: backward traceability can connect a requirement to its origin."],"ref":"BABOK Guide v3 §5.1 Trace Requirements, printed pp. 78–82; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q534","domains":[4],"level":4,"tag":"","q":"Which impacts may be considered when assessing a proposed requirement change?","opts":["Effects on related requirements and designs","Potential change to value, risk, cost, or schedule","Compatibility with governance and approval processes","Only the size of the text edit"],"answer":[0,1,2],"why":["Correct: related requirements and designs may be affected.","Correct: assessment considers consequences for value and delivery constraints.","Correct: the proposal must be considered through the applicable governance process.","Text length does not establish the significance of a change."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 94–97; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":true,"sourceSet":"ecba-set-12.html"},{"id":"q535","domains":[4],"level":5,"tag":"","q":"Which statement most accurately relates inputs, guidelines/tools, techniques, and stakeholders in task planning?","opts":["Inputs provide information used by the task; guidelines/tools shape its conduct; techniques are methods applied; stakeholders provide or use relevant expertise and decisions","Inputs are optional outputs; guidelines/tools are stakeholders; techniques are approval records","Techniques define the task’s authority; stakeholders are selected only after the task is complete","Guidelines/tools replace the need to consider inputs or stakeholder participation"],"answer":[0],"why":["Correct: these categories play distinct roles in organizing and performing a BABOK task.","Each category is incorrectly described.","Governance defines authority, and relevant stakeholders are identified while planning, not only afterward.","Guidelines and tools supplement task information and stakeholder input rather than replace them."],"ref":"BABOK Guide v3 §3.1 Plan Business Analysis Approach, printed pp. 24–30; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q536","domains":[4],"level":5,"tag":"","q":"Which choice best distinguishes governance from the BA approach?","opts":["Governance defines decision rights and processes; the BA approach defines how BA work is planned and performed","Governance defines analysis techniques; the BA approach assigns approval authority","Governance and approach both mean the same approval workflow","Governance defines solution scope; the BA approach measures solution value"],"answer":[0],"why":["Correct: governance concerns decision authority and processes, while the approach concerns how BA work will be conducted.","This reverses the central emphasis of the two tasks.","They are related but distinct planning concerns.","Solution scope and value are addressed through other analysis work."],"ref":"BABOK Guide v3 §3.3 Plan Business Analysis Governance, printed pp. 37–41; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q537","domains":[4],"level":5,"tag":"","q":"Which sequence best reflects evidence-based BA performance improvement?","opts":["Assess performance, identify an improvement opportunity, analyze contributing factors, and recommend action","Choose an improvement action, then select measures that show it worked","Treat stakeholder feedback as proof of root cause and implement the most requested change","Compare performance only after the next initiative has ended"],"answer":[0],"why":["Correct: improvements should be grounded in assessment and analysis before actions are recommended.","Measures should not be selected solely to validate a predetermined action.","Feedback is useful evidence, but it does not by itself prove root cause or determine the best action.","Assessment can occur during and after work; waiting may miss timely improvement opportunities."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–50; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q538","domains":[4],"level":5,"tag":"","q":"Which statement best describes the relationship between traceability and change assessment?","opts":["Traceability reveals relationships that inform impact analysis; change assessment evaluates the proposal and its consequences","Traceability approves changes while assessment records their source","Complete traceability makes impact assessment unnecessary","Change assessment creates traceability only after a change is accepted"],"answer":[0],"why":["Correct: trace links provide relationship information that supports, but does not replace, change assessment.","Approval authority comes from governance; traceability does not approve changes.","Even complete trace links do not evaluate value, risk, cost, or other consequences.","Existing relationships are useful in assessing a proposal before a decision."],"ref":"BABOK Guide v3 §5.4 Assess Requirements Changes, printed pp. 94–97; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q539","domains":[4],"level":5,"tag":"","q":"Which choice most fully describes a viable change strategy?","opts":["A reasoned path from current to future state that accounts for transition, sequencing, readiness, risks, and constraints","A future-state description with requirements but no transition decisions","A delivery calendar based only on technical dependencies","A decision record that confirms approval of the preferred solution"],"answer":[0],"why":["Correct: a viable strategy connects the states and addresses how change can be achieved in context.","A future-state description alone does not establish a transition path.","Technical dependencies matter but do not alone determine the change strategy.","Approval records a decision but does not define the transition strategy."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–130; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q540","domains":[4],"level":5,"tag":"","q":"A measure improves while the intended outcome does not. Which is the soundest analytical response?","opts":["Check alignment between the measure and outcome, examine data and context, and investigate the divergence","Conclude the outcome was achieved because the measure improved","Replace the outcome with the measure to simplify reporting","Discard the measure and all related performance information"],"answer":[0],"why":["Correct: the divergence calls for examining relevance, data quality, and contextual factors.","An improving proxy does not prove that the intended outcome improved.","Measures inform assessment; they should not redefine the objective.","The evidence may remain useful even if the measure is incomplete or misaligned."],"ref":"BABOK Guide v3 §8.2 Analyze Performance Measures, printed pp. 170–172; ECBA Exam Blueprint v1.12 p. 2, Domain 4: Change","multi":false,"sourceSet":"ecba-set-12.html"},{"id":"q541","domains":[5],"level":1,"tag":"Value","q":"What is the purpose of Identify Business Analysis Performance Improvements?","opts":["Assess business analysis work and plan to improve processes where required","Measure solution performance in relation to the value it brings","Compare design options and recommend the option with greatest potential value","Assess stakeholder collaboration and approve changes to the engagement approach"],"answer":[0],"why":["Correct: this is the stated purpose of §3.5.","This is the purpose of Measure Solution Performance.","This is the purpose of Analyze Potential Value and Recommend Solution.","Stakeholder collaboration is a related activity, not the purpose of §3.5."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–51; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q542","domains":[5],"level":2,"tag":"Value","q":"Which are inputs to Identify Business Analysis Performance Improvements?","opts":["Performance Objectives (external)","Organizational Performance Standards","Business Analysis Performance Assessment","Business Analysis Approach"],"answer":[0,3],"why":["Correct: external performance objectives describe desired performance outcomes.","Organizational Performance Standards are a guideline/tool, not an input.","Business Analysis Performance Assessment is the task output.","Correct: the Business Analysis Approach identifies planned deliverables, activities, and techniques."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–51; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q543","domains":[5],"level":3,"tag":"Value","q":"What does the Business Analysis Performance Assessment output include?","opts":["Proposed approaches to address issues and other findings","A ranked list of requirements and designs","A comparison of planned and actual performance","Root causes of variances from expected performance"],"answer":[0,2,3],"why":["Correct: it can include proposed approaches and other findings about BA processes.","Prioritized requirements and designs are outputs of Prioritize Requirements.","Correct: the assessment compares planned and actual performance.","Correct: it identifies root causes of variances."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–51; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q544","domains":[5],"level":4,"tag":"Value","q":"Which technique is used to identify recommended changes to BA processes, deliverables, templates, and organizational process assets?","opts":["Metrics and Key Performance Indicators","Lessons Learned","Item Tracking","Observation"],"answer":[1],"why":["Metrics and KPIs help determine appropriate performance measures and tracking.","Correct: Lessons Learned can identify recommended changes for current and future work.","Item Tracking records issues for later resolution.","Observation witnesses BA performance."],"ref":"BABOK Guide v3 §3.5 Identify Business Analysis Performance Improvements, printed pp. 47–51; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q545","domains":[5],"level":5,"tag":"Value","q":"When is business analysis information considered communicated?","opts":["When target stakeholders understand its content and implications","When it is distributed to the stakeholder list","When the business analyst completes a package","When the information is approved by the sponsor"],"answer":[0],"why":["Correct: shared understanding of content and implications is the criterion.","Distribution does not by itself establish understanding.","Package preparation alone does not demonstrate shared understanding.","Approval may follow communication but is not its definition."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q546","domains":[5],"level":1,"tag":"Value","q":"Which are inputs to Communicate Business Analysis Information?","opts":["Stakeholder Engagement Approach","Elicitation Activity Plan","Requirements (approved) only","Business Analysis Information"],"answer":[0,3],"why":["Correct: the approach describes stakeholder groups, roles, and general communication needs.","This is an input to Conduct Elicitation.","Approved requirements may be communicated, but they are not the only listed input.","Correct: information becomes an input when there is a need to communicate it to additional stakeholders."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q547","domains":[5],"level":2,"tag":"Value","q":"Which technique is typically used for group communication, feedback, consensus, and approvals?","opts":["Reviews","Surveys or Questionnaires","Workshops","Interviews"],"answer":[2],"why":["Reviews may be individual or group, but this choice asks which technique is typically used for group collaboration.","Surveys gather responses; they are not the described group discussion technique.","Correct: Workshops are typically used during group collaboration and can support feedback, consensus, and approvals.","Interviews communicate information individually."],"ref":"BABOK Guide v3 §4.4 Communicate Business Analysis Information, printed pp. 67–71; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q548","domains":[5],"level":3,"tag":"Value","q":"What is the purpose of Prioritize Requirements?","opts":["Assess the implications of proposed changes to requirements and designs","Rank requirements in order of relative importance","Validate that requirements align with business objectives","Determine how requirements relate to solution components"],"answer":[1],"why":["This describes Assess Requirements Changes.","Correct: prioritization ranks requirements by relative importance.","This describes Validate Requirements.","This describes Trace Requirements."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–91; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q549","domains":[5],"level":4,"tag":"Value","q":"Which inputs are accepted by Prioritize Requirements?","opts":["Requirements ready to prioritize, including text, matrices, or diagrams","Designs ready to prioritize, including text, prototypes, or diagrams","Requirements (validated) only","Requirements Change Assessment"],"answer":[0,1],"why":["Correct: requirements in these forms may be input when ready to prioritize.","Correct: designs in these forms may also be input when ready to prioritize.","Validation may be relevant, but the task input is stated more broadly as Requirements.","This is an output of Assess Requirements Changes, not a listed input here."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–91; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q550","domains":[5],"level":5,"tag":"Value","q":"Which factors may influence the basis for prioritization?","opts":["Cost and risk","Dependencies and time sensitivity","Alphabetical order of requirement identifiers","Benefit and penalty"],"answer":[0,1,3],"why":["Correct: cost and risk can influence relative priority.","Correct: dependencies and time sensitivity can also be considered.","Identifier order is not a value-based prioritization factor.","Correct: benefit is a typical prioritization factor."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–91; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q551","domains":[5],"level":1,"tag":"Value","q":"Which stakeholder role is matched correctly to its contribution to prioritization?","opts":["Regulator—allocates requirements to releases in the project plan","Customer—approves solution measures used to determine performance","Implementation Subject Matter Expert—provides input about technical dependencies and may negotiate based on technical constraints","Project Manager—verifies that requirements deliver value from the customer perspective"],"answer":[2],"why":["The Regulator checks consistency with legal and regulatory constraints.","The Sponsor approves performance measures; the Customer can verify customer/end-user value.","Correct: the Implementation Subject Matter Expert provides input on technical dependencies and constraints.","The Project Manager uses priorities in project planning and release allocation."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–91; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q552","domains":[5],"level":2,"tag":"Value","q":"Which statements are outputs of Define Future State?","opts":["Business Analysis Performance Assessment","Future State Description","Business Objectives","Potential Value"],"answer":[1,2,3],"why":["Business Analysis Performance Assessment is the output of §3.5.","Correct: Future State Description is an output.","Correct: Business Objectives are an output.","Correct: Potential Value is an output."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q553","domains":[5],"level":3,"tag":"Value","q":"Which statement accurately describes a business goal in defining a future state?","opts":["A longer-term, ongoing, qualitative statement of a state or condition the organization seeks to establish and maintain","A short-term, quantitative measure of solution performance only","A set of requirements ranked by relative importance","A description of risks that may affect the change strategy"],"answer":[0],"why":["Correct: this reflects the BABOK description of business goals.","This is closer to a measurable objective or performance measure, not the definition of a goal.","This is prioritized requirements.","This describes risk information, not a business goal."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q554","domains":[5],"level":4,"tag":"Value","q":"Which technique helps identify what makes a future state acceptable or how options may be evaluated?","opts":["Balanced Scorecard","Benchmarking and Market Analysis","Process Modelling","Acceptance and Evaluation Criteria"],"answer":[3],"why":["A Balanced Scorecard can set targets for measuring the future state.","Benchmarking compares performance with external baselines.","Process Modelling depicts a process; it is not the technique described.","Correct: this technique identifies acceptance and evaluation criteria for the future state."],"ref":"BABOK Guide v3 §6.2 Define Future State, printed pp. 110–119; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q555","domains":[5],"level":5,"tag":"Value","q":"What is the purpose of Define Change Strategy?","opts":["Estimate potential value for each design option and recommend a solution","Measure solution performance against value delivered","Develop and assess alternative approaches to the change, then select the recommended approach","Define the set of conditions needed to meet the business need"],"answer":[2],"why":["This is Analyze Potential Value and Recommend Solution.","This is Measure Solution Performance.","Correct: this is the stated purpose of Define Change Strategy.","This is Define Future State."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–131; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q556","domains":[5],"level":1,"tag":"Value","q":"Which are inputs to Define Change Strategy?","opts":["Stakeholder Engagement Approach","Current State Description","Future State Description","Risk Analysis Results"],"answer":[0,1,2,3],"why":["Correct: stakeholder communication and collaboration needs can identify activities for the strategy.","Correct: the Current State Description provides context for the change.","Correct: the Future State Description provides context about the desired state.","Correct: Risk Analysis Results describe risks and exposure."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–131; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q557","domains":[5],"level":2,"tag":"Value","q":"Which outputs are produced by Define Change Strategy?","opts":["Change Strategy","Solution Scope","Requirements (prioritized)","Solution Recommendation"],"answer":[0,1],"why":["Correct: Change Strategy is an output.","Correct: Solution Scope is an output.","Prioritized requirements are produced by Prioritize Requirements.","Solution Recommendation is produced by Analyze Potential Value and Recommend Solution."],"ref":"BABOK Guide v3 §6.4 Define Change Strategy, printed pp. 124–131; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q558","domains":[5],"level":3,"tag":"Value","q":"What is the purpose of Validate Requirements?","opts":["Ensure requirements and designs meet quality standards and are usable for their purpose","Confirm elicitation results are accurate and consistent","Ensure approved requirements are ready for development","Ensure requirements and designs align with business requirements and support delivery of needed value"],"answer":[3],"why":["This describes Verify Requirements.","This describes Confirm Elicitation Results.","This describes the result of approval, not validation’s purpose.","Correct: validation checks alignment with business requirements and ability to deliver value."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q559","domains":[5],"level":4,"tag":"Value","q":"What is the stated input and output for Validate Requirements?","opts":["Input: Elicitation Results (unconfirmed); output: Elicitation Results (confirmed)","Input: Design Options; output: Solution Recommendation","Input: Requirements (specified and modelled); output: Requirements (validated)","Input: Requirements (verified); output: Requirements (approved)"],"answer":[2],"why":["This is the input/output sequence for elicitation confirmation.","These relate to defining design options and recommending a solution.","Correct: §7.3 uses specified and modelled requirements as input and produces validated requirements.","Verified requirements are an input to Approve Requirements; approved requirements are its output."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q560","domains":[5],"level":5,"tag":"Value","q":"Which activities are elements of Validate Requirements?","opts":["Approve requirements according to governance authority","Identify assumptions so associated risks can be managed","Define measurable evaluation criteria","Compare design options using net present value"],"answer":[1,2],"why":["Approval is performed in Approve Requirements.","Correct: identifying assumptions is an element of validation.","Correct: defining measurable evaluation criteria is an element.","This is a financial analysis technique used in value assessment, not an element of validation."],"ref":"BABOK Guide v3 §7.3 Validate Requirements, printed pp. 144–147; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q561","domains":[5],"level":1,"tag":"Value","q":"What does Analyze Potential Value and Recommend Solution establish?","opts":["Estimated potential value for each design option and which option is most appropriate to meet enterprise requirements","Whether each requirement should be maintained for reuse","Whether the future state is achievable with available resources","How the change strategy will be approved"],"answer":[0],"why":["Correct: the task estimates each option’s potential value and establishes the most appropriate solution.","This describes Maintain Requirements.","This is part of Define Future State.","Governance defines approval processes; this is not the purpose of §7.6."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–162; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q562","domains":[5],"level":2,"tag":"Value","q":"Which are inputs to Analyze Potential Value and Recommend Solution?","opts":["Design Options","Requirements (approved) only","Solution Performance Measures","Potential Value"],"answer":[0,3],"why":["Correct: Design Options are compared to recommend a solution.","The task inputs are Potential Value and Design Options, not approved requirements only.","Solution Performance Measures are an input to later solution evaluation tasks.","Correct: Potential Value is a benchmark for evaluating value delivered by a design."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–162; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q563","domains":[5],"level":3,"tag":"Value","q":"What is the output Solution Recommendation?","opts":["A list of risks and their mitigation strategies","An approach for guiding the organization through the change","The suggested most appropriate solution based on evaluating defined design options, intended to maximize enterprise value","A ranked set of requirements for additional work"],"answer":[2],"why":["This describes Risk Analysis Results.","This describes Change Strategy.","Correct: this describes Solution Recommendation.","This describes prioritized requirements."],"ref":"BABOK Guide v3 §7.6 Analyze Potential Value and Recommend Solution, printed pp. 157–162; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q564","domains":[5],"level":4,"tag":"Value","q":"What is the purpose of Measure Solution Performance?","opts":["Recommend actions to improve solution value","Define performance measures and use collected data to evaluate solution effectiveness in relation to value","Interpret performance measures to provide insight into solution value","Identify the factors that create a difference between potential and actual value"],"answer":[1],"why":["This is the action-recommendation task, not measurement.","Correct: this is the purpose of Measure Solution Performance.","This is Analyze Performance Measures.","This is part of Recommend Actions to Increase Solution Value."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–170; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q565","domains":[5],"level":5,"tag":"Value","q":"Which are inputs to Measure Solution Performance?","opts":["Business Objectives","Implemented Solution (external)","Requirements (approved)","Solution Recommendation"],"answer":[0,1],"why":["Correct: Business Objectives provide measurable results against which performance can be assessed.","Correct: an implemented solution may be operating, a prototype, pilot, or beta.","Approved requirements are not one of the two inputs listed for this task.","Solution Recommendation is produced by §7.6 and is not a listed input here."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–170; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q566","domains":[5],"level":1,"tag":"Value","q":"What output defines measures that show how well a solution is performing or potentially could perform?","opts":["Solution Performance Analysis","Recommended Actions","Potential Value","Solution Performance Measures"],"answer":[3],"why":["Performance Analysis is an output of Analyze Performance Measures.","Recommended Actions is the output of §8.5.","Potential Value is a guideline/benchmark used in value analysis, not this task output.","Correct: Solution Performance Measures provide information on actual or potential solution performance."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–170; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q567","domains":[5],"level":2,"tag":"Value","q":"Which role is responsible for approving measures used to determine solution performance and may provide performance expectations?","opts":["End User","Project Manager","Sponsor","Customer"],"answer":[2],"why":["The End User contributes to realized value and can provide feedback.","The Project Manager manages the schedule and measurement tasks.","Correct: the Sponsor approves the measures and may provide performance expectations.","The Customer may provide feedback on solution performance."],"ref":"BABOK Guide v3 §8.1 Measure Solution Performance, printed pp. 166–170; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q568","domains":[5],"level":3,"tag":"Value","q":"What is the purpose of Recommend Actions to Increase Solution Value?","opts":["Prioritize requirements by relative importance","Understand factors creating differences between potential and actual value, then recommend a course of action to align them","Measure performance measures and determine the solution’s effectiveness","Estimate the value of each design option and choose a solution"],"answer":[1],"why":["This is Prioritize Requirements.","Correct: this is the purpose stated for §8.5.","This is Measure Solution Performance.","This is Analyze Potential Value and Recommend Solution."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–186; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q569","domains":[5],"level":4,"tag":"Value","q":"Which statements correctly pair the inputs and output of Recommend Actions to Increase Solution Value?","opts":["Enterprise Limitation is an input","Solution Limitation is an input","Recommended Actions is the output","Business Objectives is an input"],"answer":[0,1,2],"why":["Correct: Enterprise Limitation is an input.","Correct: Solution Limitation is an input.","Correct: Recommended Actions is the output.","Business Objectives is a guideline/tool, not a listed input."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–186; BACCM™ Core Concept: Value","multi":true,"sourceSet":"ecba-set-13-value.html"},{"id":"q570","domains":[5],"level":5,"tag":"Value","q":"Which stakeholder role is correctly matched to Recommend Actions to Increase Solution Value?","opts":["Regulator—estimates costs of design options","End User—approves funding for recommended actions","Customer—ensures compliance with laws and regulations","Sponsor—authorizes and ensures funding for implementation of recommended actions"],"answer":[3],"why":["Implementation Subject Matter Experts help identify potential implementation costs; Regulators address compliance.","Funding authority belongs to the Sponsor.","Regulatory compliance is the Regulator’s role.","Correct: the Sponsor authorizes and ensures funding for implementing recommended actions."],"ref":"BABOK Guide v3 §8.5 Recommend Actions to Increase Solution Value, printed pp. 182–186; BACCM™ Core Concept: Value","multi":false,"sourceSet":"ecba-set-13-value.html"},{"id":"q571","domains":[5],"level":1,"tag":"","q":"Which statements accurately describe Prepare for Elicitation?","opts":["Its purpose is to understand elicitation scope, select appropriate techniques, and plan supporting materials and resources","Frequently used techniques include Brainstorming, Document Analysis, Estimation, and Interviews","Its output is Elicitation Results (Confirmed)","Its purpose is to obtain approval of requirements"],"answer":[0,1],"why":["Correct: this summarizes the BABOK purpose of §4.1.","Correct: these are techniques frequently used for §4.1.","Elicitation Results (Confirmed) is the output of Confirm Elicitation Results; §4.1 produces an Elicitation Activity Plan.","Obtaining approval is not the purpose of Prepare for Elicitation."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–60; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"},{"id":"q572","domains":[5],"level":2,"tag":"","q":"Which pair contains the inputs to Prepare for Elicitation?","opts":["Needs and Stakeholder Engagement Approach","Business Analysis Approach and Business Objectives","Elicitation Results (Unconfirmed) and Existing Business Analysis Information","Requirements (Specified and Modelled) and Solution Scope"],"answer":[0],"why":["Correct: Needs and Stakeholder Engagement Approach are the two inputs listed in BABOK Guide v3 §4.1.3.","These are guidelines and tools for the task, not its two inputs.","Elicitation Results (Unconfirmed) is an input to Confirm Elicitation Results; Existing Business Analysis Information is a guideline/tool there.","These are relevant to other requirements analysis tasks, not the inputs listed for §4.1."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–60; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q573","domains":[5],"level":3,"tag":"","q":"What is the output of Prepare for Elicitation?","opts":["Elicitation Activity Plan","Elicitation Results (Unconfirmed)","Elicitation Results (Confirmed)","Business Analysis Information (Communicated)"],"answer":[0],"why":["Correct: the task produces the Elicitation Activity Plan.","These are produced by Conduct Elicitation.","This is the output of Confirm Elicitation Results.","This is the output of Communicate Business Analysis Information."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–60; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q574","domains":[5],"level":4,"tag":"","q":"Which option lists the three specific stakeholder roles named for Prepare for Elicitation in BABOK Guide v3 §4.1.7?","opts":["Domain Subject Matter Expert, Project Manager, Sponsor","Domain Subject Matter Expert, Project Manager, Regulator","Domain Subject Matter Expert, Project Manager, Supplier","Domain Subject Matter Expert, Project Manager, Customer"],"answer":[0],"why":["Correct: BABOK Guide v3 §4.1.7 names the Domain Subject Matter Expert, Project Manager, and Sponsor, in addition to any other stakeholder.","A regulator may be involved as another stakeholder when relevant, but is not one of the three specific roles in this list.","A supplier may be involved when relevant, but is not one of the three specific roles in this list.","A customer may be involved when relevant, but is not one of the three specific roles in this list."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–60; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q575","domains":[5],"level":5,"tag":"","q":"Which items are listed as guidelines and tools for Prepare for Elicitation?","opts":["Business Analysis Approach","Business Objectives","Existing Business Analysis Information","Potential Value"],"answer":[0,1,2,3],"why":["Correct: Business Analysis Approach is listed as a guideline/tool.","Correct: Business Objectives is listed as a guideline/tool.","Correct: Existing Business Analysis Information is listed as a guideline/tool.","Correct: Potential Value is listed as a guideline/tool."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–60; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"},{"id":"q576","domains":[5],"level":1,"tag":"","q":"Which activities are elements of Prepare for Elicitation?","opts":["Understand the scope of elicitation","Select elicitation techniques","Set up logistics and secure supporting material","Prepare stakeholders"],"answer":[0,1,2,3],"why":["Correct: understanding the scope is an element.","Correct: selecting elicitation techniques is an element.","Correct: setting up logistics and securing supporting material are elements.","Correct: preparing stakeholders is an element."],"ref":"BABOK Guide v3 §4.1 Prepare for Elicitation, printed pp. 56–60; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"},{"id":"q577","domains":[5],"level":1,"tag":"","q":"What is the purpose of Confirm Elicitation Results?","opts":["Check elicitation information for accuracy and consistency with other information","Choose the scope and logistics for an elicitation activity","Rank requirements in order of relative importance","Ensure requirements align with business requirements and deliver needed value"],"answer":[0],"why":["Correct: §4.3 checks information gathered during elicitation for accuracy and consistency.","Scoping and logistics are addressed by Prepare for Elicitation.","Ranking requirements is Prioritize Requirements.","Aligning requirements to business requirements and value is Validate Requirements."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–66; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q578","domains":[5],"level":2,"tag":"","q":"Which input-to-output pair corresponds to Confirm Elicitation Results?","opts":["Elicitation Results (Unconfirmed) → Elicitation Results (Confirmed)","Elicitation Activity Plan → Elicitation Results (Unconfirmed)","Needs → Elicitation Activity Plan","Requirements (Specified and Modelled) → Requirements (Validated)"],"answer":[0],"why":["Correct: Confirm Elicitation Results transforms unconfirmed elicitation results into confirmed elicitation results.","The Elicitation Activity Plan is the output of Prepare for Elicitation and guides Conduct Elicitation.","Needs is an input to Prepare for Elicitation; the task produces an Elicitation Activity Plan.","This pairs inputs and outputs from different tasks; Validate Requirements follows specified and modelled requirements."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–66; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q579","domains":[5],"level":3,"tag":"","q":"Which resources are listed as guidelines and tools for Confirm Elicitation Results?","opts":["Elicitation Activity Plan and Existing Business Analysis Information","Stakeholder Engagement Approach and Needs","Business Objectives and Potential Value","Requirements Architecture and Solution Scope"],"answer":[0],"why":["Correct: both the Elicitation Activity Plan and Existing Business Analysis Information are listed.","These are inputs and guidelines for Prepare for Elicitation, not the listed resources for §4.3.","These guide Validate Requirements, not Confirm Elicitation Results.","These are guidelines/tools used in requirements analysis tasks, not the §4.3 list."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–66; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q580","domains":[5],"level":4,"tag":"","q":"Which are techniques listed for Confirm Elicitation Results?","opts":["Document Analysis","Interviews","Reviews","Workshops"],"answer":[0,1,2,3],"why":["Correct: Document Analysis is listed for §4.3.","Correct: Interviews are listed for §4.3.","Correct: Reviews are listed for §4.3.","Correct: Workshops are listed for §4.3."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–66; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"},{"id":"q581","domains":[5],"level":5,"tag":"","q":"Which statement best describes the stakeholders for Confirm Elicitation Results?","opts":["Domain Subject Matter Experts and any stakeholders who can help confirm the information","Sponsors, Project Managers, and Domain Subject Matter Experts only","Customers, End Users, and Regulators only","Implementation Subject Matter Experts and Project Managers only"],"answer":[0],"why":["Correct: §4.3 identifies Domain Subject Matter Experts and any stakeholder who may need to participate.","This is the specific trio for Prepare for Elicitation, not the §4.3 stakeholder definition.","These roles may participate if relevant, but this is not the stakeholder definition for §4.3.","This is not the stakeholder definition for confirming elicitation results."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–66; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q582","domains":[5],"level":2,"tag":"","q":"Which actions correspond to the elements of Confirm Elicitation Results?","opts":["Compare elicitation results against source information","Compare elicitation results against other elicitation results","Compare results against solution performance after implementation","Obtain approval of requirements from the sponsor"],"answer":[0,1],"why":["Correct: comparing results against source information is an element.","Correct: comparing results against other elicitation results is an element.","Solution performance measurement is not a §4.3 element.","Approval is a separate task; confirmation checks accuracy and consistency."],"ref":"BABOK Guide v3 §4.3 Confirm Elicitation Results, printed pp. 65–66; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"},{"id":"q583","domains":[5],"level":1,"tag":"","q":"Which statements accurately describe Prioritize Requirements?","opts":["It ranks requirements in order of relative importance","Prioritization is ongoing; priorities can change as context changes and may account for dependencies","Priority refers only to implementation sequence, not relative value","Its purpose is to approve requirements for implementation"],"answer":[0,1],"why":["Correct: this is the task purpose in §5.3.1.","Correct: prioritization is ongoing, and inter-dependencies may inform the basis for priority.","BABOK says priority can refer to relative value or implementation sequence.","Approval is addressed by Approve Requirements, not Prioritize Requirements."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"},{"id":"q584","domains":[5],"level":2,"tag":"","q":"Which items are inputs to Prioritize Requirements?","opts":["Requirements and Designs that are ready to prioritize","Requirements (Specified and Modelled) only","Requirements (Validated) and Elicitation Results (Confirmed)","Requirements (Approved) and Solution Recommendation"],"answer":[0],"why":["Correct: BABOK Guide v3 §5.3.3 lists Requirements and Designs ready to prioritize.","The inputs are not limited to specified and modelled requirements.","These do not constitute the listed input pair for §5.3.","These are not the inputs listed for Prioritize Requirements."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q585","domains":[5],"level":3,"tag":"","q":"Which outputs are produced by Prioritize Requirements?","opts":["Requirements (Prioritized) and Designs (Prioritized)","Requirements (Approved) and Designs (Approved)","Requirements (Validated) and Designs (Validated)","Requirements (Maintained) and Designs (Maintained)"],"answer":[0],"why":["Correct: §5.3 produces Requirements (Prioritized) and Designs (Prioritized).","Approval is produced by Approve Requirements.","Validation is produced by Validate Requirements.","“Maintained” is not the output state for §5.3."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":false,"sourceSet":"ecba-set-13.html"},{"id":"q586","domains":[5],"level":4,"tag":"","q":"Which are guidelines and tools listed for Prioritize Requirements?","opts":["Business Constraints","Change Strategy","Domain Knowledge","Business Objectives"],"answer":[0,1,2],"why":["Correct: Business Constraints are listed for §5.3.","Correct: Change Strategy is listed for §5.3.","Correct: Domain Knowledge is listed for §5.3.","Business Objectives is listed for Validate Requirements, not the §5.3 list."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"},{"id":"q587","domains":[5],"level":5,"tag":"","q":"Which are techniques frequently used for Prioritize Requirements?","opts":["Backlog Management","Decision Analysis","Prioritization","Functional Decomposition"],"answer":[0,1,2],"why":["Correct: Backlog Management is listed as a frequently used technique for §5.3.","Correct: Decision Analysis is listed for §5.3.","Correct: Prioritization is listed for §5.3.","Functional Decomposition is not in the frequently used technique list for §5.3."],"ref":"BABOK Guide v3 §5.3 Prioritize Requirements, printed pp. 86–90; ECBA Exam Blueprint v1.12 p. 2, Domain 5: Needs and Solutions","multi":true,"sourceSet":"ecba-set-13.html"}]);